using Monitor.Core;

namespace Monitor.App;
internal sealed record DetectionEditorGroup(string Title, string Description, string[] Properties, bool? LocalMode = null);
internal static class DetectionEditorLayout
{
    public static readonly DetectionEditorGroup[] Groups = [new("通用设置", "采样频率与检测区域作用于图像分析；恢复时间作用于事件结束确认。", [nameof(DetectionSettings.AnalysisFps), nameof(DetectionSettings.RoiX), nameof(DetectionSettings.RoiY), nameof(DetectionSettings.RoiWidth), nameof(DetectionSettings.RoiHeight), nameof(DetectionSettings.RecoverySeconds)]), new("黑画面检测", "SDR与HDR分别使用对应的黑色阈值。", [nameof(DetectionSettings.BlackEnabled), nameof(DetectionSettings.BlackLevel), nameof(DetectionSettings.HdrBlackNits), nameof(DetectionSettings.BlackRatio), nameof(DetectionSettings.BlackSeconds)]), new("灰屏检测", "独立于局部/旧版模式。识别低色度且颜色均匀的区域；默认覆盖ROI至少80%、持续1秒。正常灰色背景也可能满足条件，需人工复核。", [nameof(DetectionSettings.GrayEnabled), nameof(DetectionSettings.GrayMinAreaPercent), nameof(DetectionSettings.GrayChromaLimit), nameof(DetectionSettings.GrayUniformity), nameof(DetectionSettings.GrayMinLevel), nameof(DetectionSettings.GrayMaxLevel), nameof(DetectionSettings.GraySeconds), nameof(DetectionSettings.GrayRecordBrief)]), new("静帧检测", "局部运动保护开启后，以下保护参数才参与静帧判断。", [nameof(DetectionSettings.FreezeEnabled), nameof(DetectionSettings.FreezeDifference), nameof(DetectionSettings.FreezeSeconds), nameof(DetectionSettings.FreezeLocalMotionProtection), nameof(DetectionSettings.FreezePixelDifference), nameof(DetectionSettings.FreezeBlockChangedPercent), nameof(DetectionSettings.FreezeMotionAreaPercent), nameof(DetectionSettings.FreezeReferenceSeconds), nameof(DetectionSettings.FreezeMotionHoldSeconds)]), new("画面异常检测模式", "选择一种检测模式，下方不适用的参数组会置灰。切换模式保留各组已填写的值。", [nameof(DetectionSettings.MosaicEnabled), nameof(DetectionSettings.FlowerEnabled), nameof(DetectionSettings.VisualLocalEnabled)]), new("局部检测参数", "通过区域结构和同一区域的时间证据确认；分数不是故障概率，结果需人工复核。", [nameof(DetectionSettings.VisualSensitivity), nameof(DetectionSettings.VisualMinAreaPercent), nameof(DetectionSettings.VisualRecordBrief), nameof(DetectionSettings.VisualConfirmWindowSeconds), nameof(DetectionSettings.VisualMinimumHits)], true), new("局部模式：绿屏检测", "绿色填充独立判断，不将其周围的普通轮廓直接归为马赛克。", [nameof(DetectionSettings.GreenEnabled), nameof(DetectionSettings.VisualGreenAreaPercent)], true), new("旧版全局参数", "仅选择旧版全局检测时生效；分数与连续持续时间均不作用于局部模式。", [nameof(DetectionSettings.MosaicScore), nameof(DetectionSettings.MosaicSeconds), nameof(DetectionSettings.FlowerScore), nameof(DetectionSettings.FlowerSeconds)], false), new("静音检测", "选定声道的编号从0开始；不改变实际监听的声道。", [nameof(DetectionSettings.SilenceEnabled), nameof(DetectionSettings.SilenceDb), nameof(DetectionSettings.SilenceSeconds), nameof(DetectionSettings.SilentChannels)]), new("音频间断检测", "检测解码后音频的时间间断。", [nameof(DetectionSettings.AudioGapEnabled), nameof(DetectionSettings.AudioGapSeconds)]), new("解码与音视频中断", "解码提示与画面异常分别记录。", [nameof(DetectionSettings.DecodeEnabled), nameof(DetectionSettings.LossEnabled), nameof(DetectionSettings.LossSeconds)])];
    public static bool Enabled(string property, Func<string, bool> selected)
    {
        bool local = selected(nameof(DetectionSettings.VisualLocalEnabled));
        return property switch
        {
            nameof(DetectionSettings.GrayMinAreaPercent) or nameof(DetectionSettings.GrayChromaLimit) or nameof(DetectionSettings.GrayUniformity) or nameof(DetectionSettings.GrayMinLevel) or nameof(DetectionSettings.GrayMaxLevel) or nameof(DetectionSettings.GraySeconds) or nameof(DetectionSettings.GrayRecordBrief) => selected(nameof(DetectionSettings.GrayEnabled)),
            nameof(DetectionSettings.BlackLevel) or nameof(DetectionSettings.HdrBlackNits) or nameof(DetectionSettings.BlackRatio) or nameof(DetectionSettings.BlackSeconds) => selected(nameof(DetectionSettings.BlackEnabled)),
            nameof(DetectionSettings.FreezeDifference) or nameof(DetectionSettings.FreezeSeconds) or nameof(DetectionSettings.FreezeLocalMotionProtection) => selected(nameof(DetectionSettings.FreezeEnabled)),
            nameof(DetectionSettings.FreezePixelDifference) or nameof(DetectionSettings.FreezeBlockChangedPercent) or nameof(DetectionSettings.FreezeMotionAreaPercent) or nameof(DetectionSettings.FreezeReferenceSeconds) or nameof(DetectionSettings.FreezeMotionHoldSeconds) => selected(nameof(DetectionSettings.FreezeEnabled)) && selected(nameof(DetectionSettings.FreezeLocalMotionProtection)),
            nameof(DetectionSettings.VisualSensitivity) or nameof(DetectionSettings.VisualMinAreaPercent) or nameof(DetectionSettings.VisualRecordBrief) or nameof(DetectionSettings.VisualConfirmWindowSeconds) or nameof(DetectionSettings.VisualMinimumHits) => local && (selected(nameof(DetectionSettings.MosaicEnabled)) || selected(nameof(DetectionSettings.FlowerEnabled)) || selected(nameof(DetectionSettings.GreenEnabled))),
            nameof(DetectionSettings.GreenEnabled) => local,
            nameof(DetectionSettings.VisualGreenAreaPercent) => local && selected(nameof(DetectionSettings.GreenEnabled)),
            nameof(DetectionSettings.MosaicScore) or nameof(DetectionSettings.MosaicSeconds) => !local && selected(nameof(DetectionSettings.MosaicEnabled)),
            nameof(DetectionSettings.FlowerScore) or nameof(DetectionSettings.FlowerSeconds) => !local && selected(nameof(DetectionSettings.FlowerEnabled)),
            nameof(DetectionSettings.SilenceDb) or nameof(DetectionSettings.SilenceSeconds) or nameof(DetectionSettings.SilentChannels) => selected(nameof(DetectionSettings.SilenceEnabled)),
            nameof(DetectionSettings.AudioGapSeconds) => selected(nameof(DetectionSettings.AudioGapEnabled)),
            nameof(DetectionSettings.LossSeconds) => selected(nameof(DetectionSettings.LossEnabled)),
            _ => true
        };
    }
}
